grid:


	[#PIVOT#][#PIVOT#]

		[#FIELDS#]




			[#VIEW#]






			select 'load$GridReport$(this);[#SCRIPT#]load$CheckingReport$(this);[#SCRIPT#]' as message
	return

		[#REPORTTAG#]


			select 'scatter$GridReport$(this);' as message
	return

		[#REPORTTAG#]


			select 'dispose$GridReport$(this);[#SCRIPT#]dispose$CheckingReport$(this);[#SCRIPT#]' as message
	return






			&JavascriptReportInit;[#SCRIPT#]

function load$CheckingReport$(g) {   
	g.add_commandEvent(on$GridCheckingReport$ExecuteCommand);[#REPORTTAG#]
	g._$k = [];
	g._$i = g._getColumnOrder('[#TAGFIELD#]');
	g._$t = g._getColumnOrder('tag');
	g._$f = 'keys';[#REPORTTAG#]
}[#REPORTTAG#]
function scatter$GridReport$(g){
  fill$Grid(g, true);
  /*var c = g._getColumnOrder('sysprint');
  var t = g._getColumnOrder('tag')
  for (var i = 1; i <= g._rowCount; i++) {
    if (g._getItemValue(i, c) == 0) g._getItem(i, t).disabled = true;
  }*/
  if (g._rowCount > 0){
    g._activeRow = g._rowCount;
    g._activeColumn = g._$t;
    g._activeCell = g._getItem(g._activeRow, g._activeColumn);
  }
}[#REPORTTAG#]
function dispose$Grid(g) {[#REPORTTAG#] 
	g._$k = g._$i = g._$t = g._$f = null;[#REPORTTAG#]
	try {g.remove_commandEvent(on$GridCheckingReport$ExecuteCommand);} catch (ex) {} 
}
function on$GridCheckingReport$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, id = g.get_id(), s = String.format('$find(\'{0}\')._focusWhenTabChanged();', id);
	switch (action) {			
		case 'Print':[#REPORTTAG#]	
			e.type.cancelEvent = !isCheck$Grid(g);
			init$ExportKey(g, ',');[#REPORTTAG#]
			break;
		[#COMMANDBUTTON#]
		default:
			break;
	}
} 
[#REPORTTAG#]
			&ScriptTagReport;[#REPORTTAG#]
